{"findings":[{"tipo":"GPU","causa_raiz":"O tempo de renderização da GPU atingiu 28.27ms (69 violações), ultrapassando severamente o teto de 16.7ms (60 FPS). Isso ocorre comumente em GPUs de entrada/médias devido ao alto fillrate, overdraw, resolução nativa sem escalonamento dinâmico ou efeitos caros de pós-processamento executando em tela cheia.","codigo_refatorado":"using UnityEngine;
using UnityEngine.Rendering;

public class DynamicResolutionAndQualityManager : MonoBehaviour
{
    [Header("Configurações de Resolução Dinâmica")]
    [SerializeField] private float minRenderScale = 0.7f;
    [SerializeField] private float maxRenderScale = 1.0f;
    [SerializeField] private float targetFrameTimeMs = 16.0f;
    [SerializeField] private float adjustmentSpeed = 0.05f;

    private float currentRenderScale = 1.0f;
    private FrameTiming[] timings = new FrameTiming[1];

    private void Awake()
    {
        QualitySettings.vSyncCount = 0;
        Application.targetFrameRate = 60;
        currentRenderScale = maxRenderScale;
        ScalableBufferManager.ResizeBuffers(currentRenderScale, currentRenderScale);
    }

    private void Update()
    {
        FrameTimingManager.CaptureFrameTimings();
        uint captured = FrameTimingManager.GetLatestTimings(1, timings);

        if (captured > 0)
        {
            double gpuDuration = timings[0].gpuFrameTime;
            if (gpuDuration > targetFrameTimeMs)
            {
                currentRenderScale = Mathf.Max(minRenderScale, currentRenderScale - adjustmentSpeed * Time.unscaledDeltaTime * 10f);
            }
            else if (gpuDuration < targetFrameTimeMs - 2.0f)
            {
                currentRenderScale = Mathf.Min(maxRenderScale, currentRenderScale + adjustmentSpeed * Time.unscaledDeltaTime * 5f);
            }
            ScalableBufferManager.ResizeBuffers(currentRenderScale, currentRenderScale);
        }
    }
}","explicacao_didatica":"A placa de vídeo (GPU) estava sobrecarregada desenhando pixels demais para o tempo disponível de cada quadro (16.7 milissegundos). Criamos um script que monitora o tempo de trabalho da GPU e reduz dinamicamente a resolução interna do desenho (Render Scale) quando o jogo fica pesado, aliviando a carga imediatamente sem travar a taxa de quadros."},{"tipo":"GC","causa_raiz":"Pico de coleta de lixo gerando 96.2 KB de alocações e congelamento de 5.60ms de CPU por frame (Garbage Collector Spike). Ocorre por instanciação repetitiva em tempo de execução, concatenação de strings ou criação de arrays temporários dentro de loops Update.","codigo_refatorado":"using UnityEngine;
using System.Collections.Generic;

public class OptimizedObjectPool : MonoBehaviour
{
    [SerializeField] private GameObject prefab;
    [SerializeField] private int initialPoolSize = 50;

    private readonly Queue<GameObject> poolQueue = new Queue<GameObject>();

    private void Awake()
    {
        PrewarmPool();
    }

    private void PrewarmPool()
    {
        for (int i = 0; i < initialPoolSize; i++)
        {
            GameObject obj = Instantiate(prefab, transform);
            obj.SetActive(false);
            poolQueue.Enqueue(obj);
        }
    }

    public GameObject GetObject(Vector3 position, Quaternion rotation)
    {
        GameObject obj = poolQueue.Count > 0 ? poolQueue.Dequeue() : Instantiate(prefab, transform);
        obj.transform.SetPositionAndRotation(position, rotation);
        obj.SetActive(true);
        return obj;
    }

    public void ReturnObject(GameObject obj)
    {
        obj.SetActive(false);
        poolQueue.Enqueue(obj);
    }
}","explicacao_didatica":"O Garbage Collector (o 'lixeiro' da memória da Unity) teve que pausar o jogo por 5.6ms para limpar memórias temporárias descartadas. Em vez de criar (Instantiate) e destruir (Destroy) itens constantemente a cada frame, usamos o padrão de 'Object Pooling', que cria os objetos com antecedência e apenas os ativa ou desativa, mantendo o consumo de lixo zerado."}],"dicas_level_design":null}

